#!/usr/bin/env python3
"""Build AA-14 sibling viewer by reusing the existing trait-surface shell and Plotly bundle."""
from pathlib import Path
import json
from plotly.offline import get_plotlyjs

HERE = Path(__file__).resolve().parent
BASE = HERE.parent / "persona_trait_surface_viewer"
template = (BASE / "viewer_template.html").read_text()
header = '''<header><div><div class="eyebrow">Persona geometry / <span id="active-model-name">Qwen</span> / trait PCs</div><h1>Trait landscapes</h1><div class="subtitle">Personas projected onto principal components fitted only to traits.</div><div id="model-provenance">240 traits define the axes · 275 personas projected afterward</div></div><div class="count"><strong>275</strong> personas<br>240 trait landmarks</div></header>'''
toolbar = '''<div class="toolbar" aria-label="Landscape controls">
<label class="control">Model <select id="model-select"><option value="qwen">Qwen</option><option value="llama">Llama</option><option value="gemma">Gemma</option></select></label>
<label class="control">X axis <select id="x-axis"></select></label><label class="control">Y axis <select id="y-axis"></select></label><label class="control">Z axis <select id="z-axis"></select></label>
<label class="control">Layers <select id="layer-select"><option value="personas">Personas only</option><option value="traits">Traits only</option><option value="both" selected>Personas and traits</option></select></label>
<label class="control">Labels <select id="label-select"><option value="none">None</option><option value="selected" selected>Selected</option><option value="all">All</option></select></label>
<label class="control">Marker size <input id="marker-size" type="range" min="2" max="12" value="5"></label><label class="control">Opacity <input id="marker-opacity" type="range" min="30" max="100" value="85"></label>
<button id="reset-view" class="end" type="button">Reset view</button></div>'''
slider = '''<section class="slider-panel" aria-label="Search and component summary"><div class="slider-heading"><label>Trait-derived PC space <strong id="category-current">PC1 / PC2 / PC3</strong></label><span id="render-status" role="status" aria-live="polite">Loading saved projections</span></div><div class="search-row"><label>Persona search <input id="persona-search" type="search" placeholder="Find a persona"></label><label>Trait search <input id="trait-search" type="search" placeholder="Find a trait"></label><span id="variance-summary"></span></div><div id="stability-warning" class="small-note"></div></section>'''
main = '''<main><section class="canvas-wrap" aria-label="Interactive trait PC scatter"><div class="chart-title"><strong id="plot-category">Trait-derived coordinates</strong><small id="plane-caption">X Trait PC1 / Y Trait PC2 / Z Trait PC3</small></div><p id="chart-description" class="sr-only">Rotatable three-dimensional scatter. All three coordinates are trait-derived principal components. Personas are projected markers, not an axis or height.</p><div id="plot" role="img" aria-describedby="chart-description"></div><div class="legend"><span><i class="dot"></i> Projected personas</span><span><i class="trait-dot"></i> Trait landmarks</span><span>Drag to rotate · scroll to zoom</span></div></section><aside aria-label="Point inspection"><div><p class="panel-heading">Inspect a point</p><label class="sr-only" for="point-picker">Select a point</label><select id="point-picker"><option value="">Hover, search, or choose a point</option></select><h2 id="selected-name">Explore trait space</h2><div id="selection-kind">Hover a marker or choose a name</div><button id="clear-selection" type="button" hidden>Clear selection</button></div><div><div id="selected-score">--</div><div class="score-label" id="score-label">trait-space projection</div><dl><dt>X coordinate</dt><dd id="selected-x">--</dd><dt>Y coordinate</dt><dd id="selected-y">--</dd><dt>Z coordinate</dt><dd id="selected-z">--</dd><dt>Captured in first 20 PCs</dt><dd id="selected-captured">--</dd><dt>Residual norm</dt><dd id="selected-residual">--</dd><dt>Nearest traits / axis poles</dt><dd id="selected-nearest">--</dd></dl></div><div class="aside-help"><div class="rule"></div><p class="small-note" id="profile-note">PCA uses only each model's 240 trait vectors. Personas are centered using the frozen trait mean before projection. Different models have separate activation spaces.</p><p class="small-note" id="ood-note"></p></div></aside></main>'''
footer = '''<footer><details><summary>How to read this landscape</summary><div class="method-text"><p>Trait vectors—not personas—are the observations in each model's PCA. Each persona is projected afterward into that model's frozen trait-derived axes. X, Y, and Z are all selected trait PCs. The native mean-centered projection is primary; a unit-normalized sensitivity analysis is reported separately.</p><p>Variance percentages describe the trait cloud, not the persona cloud. A projected persona may lie outside the trait cloud; captured fraction is the fraction of its centered activation-vector energy represented by the first 20 trait PCs. An out-of-distribution flag compares its 20D nearest-trait distance against the 99th percentile of trait-to-trait fifth-neighbor distances.</p><p>Axis names and signs are model-specific. Unstable axes should not receive a strong standalone semantic interpretation. Correlation and subspace alignment results are in the methodology report.</p><p><a href="methodology_report.md">Methods and findings</a> · <a href="projected_personas.csv" download>Persona projections</a> · <a href="trait_pc_scores.csv" download>Trait scores</a> · <a href="../persona_trait_surface_viewer/persona_trait_surface_viewer.html">Original surface viewer</a></p></div></details></footer>'''
template = template.replace(template[template.index('<header>'):template.index('<section class="camera-bar"')], header + '\n' + toolbar + '\n' + slider + '\n')
template = template.replace(template[template.index('<main>'):template.index('<script>__PLOTLY_LIBRARY__</script>')], main + '\n' + footer + '\n')
template = template.replace('<title>Trait Landscapes | Qwen, Llama, Gemma Persona Geometry</title>', '<title>Trait PC Landscapes | Qwen, Llama, Gemma</title>')
template = template.replace('</style>', '.search-row{display:flex;flex-wrap:wrap;gap:10px 20px;align-items:center}.search-row input{background:#22262a;border:1px solid #555;padding:7px;border-radius:3px;color:var(--text)}#variance-summary{color:var(--accent);font-size:11px}.trait-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#8eb8d0}#selected-nearest{max-width:140px;text-align:right;white-space:normal}#stability-warning{color:#eabf55}</style>')
template = template.replace('__BOOTSTRAP_JS__', '')
template = template.replace('__PLOTLY_LIBRARY__', get_plotlyjs().replace('</script>', '<\\/script>'))
template = template.replace('__VIEWER_DATA__', (HERE / 'viewer_data.json').read_text().strip().replace('</script>', '<\\/script>'))
template = template.replace('__CAMERA_JS__', (BASE / 'camera_controls.js').read_text())
template = template.replace('__VIEWER_JS__', (HERE / 'viewer.js').read_text())
(HERE / 'trait_pc_persona_viewer.html').write_text(template)
print(f'Built {HERE / "trait_pc_persona_viewer.html"} ({len(template):,} characters)')
